refentry.refsect1:
&reftitle.returnvalues;


 &return.success; Restituisce una string se PGSQL_DML_STRING viene passato
 tramite flags.

  &reftitle.examples;



    Esempio di pg_update


<?php 
  $db = pg_connect('dbname=foo');
  $data = array('field1'=>'AA', 'field2'=>'BB');
  // Questo è in qualche modo sicuro, poiché viene effettuato l'escape di tutti i valori.
  // Tuttavia PostgreSQL supporta JSON/Array. Questi non sono
  // resi sicuri né dall'escape né dalle query preparate.
  $res = pg_update($db, 'post_log', $_POST, $data);
  if ($res) {
      echo "I dati sono stati aggiornati: $res\n";
  } else {
      echo "L'utente deve aver inviato input errati\n";
  }
?>
